@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Manrope:wght@300;400;500;600;700;800&display=swap');

.root {
  --vt-surface: #F4F1DE;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #3D405B;
  --vt-ink: #3D405B;
  --vt-ink-soft: #575A78;
  --vt-on-deep: #F4F1DE;
  --vt-accent: #A94B2B;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #5F8E73;
  --vt-accent-on-deep: #A8CFBA;
  --vt-line: rgba(61, 64, 91, 0.08);

  font-family: 'Manrope', 'Segoe UI', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.7;
  overflow-x: hidden;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  font-family: 'Lora', Georgia, serif;
  font-weight: 600;
  line-height: 1.2;
}

.root a {
  color: inherit;
  text-decoration: none;
}

.root img {
  max-width: 100%;
  display: block;
}

.root ul {
  list-style: none;
}

.root button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Mobile top navigation (visible only on small screens) */
.mobileNav {
  display: none;
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 0.75rem 1rem;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.mobileNavLinks {
  display: flex;
  gap: 0.5rem;
  overflow-x: auto;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0.25rem;
}

.mobileNavLinks::-webkit-scrollbar {
  display: none;
}

.mobileNavLinks a {
  padding: 0.5rem 1rem;
  border-radius: 50px;
  background: rgba(244, 241, 222, 0.1);
  color: var(--vt-on-deep);
  font-size: 0.85rem;
  font-weight: 600;
  transition: background 0.2s ease;
}

.mobileNavLinks a:hover,
.mobileNavLinks a:focus-visible {
  background: rgba(244, 241, 222, 0.2);
  outline: none;
}

/* Desktop sidebar */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: 260px;
  height: 100vh;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.sidebarBrand {
  padding: 2rem 1.5rem 1.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
}

.sidebarTagline {
  font-size: 0.75rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-top: 0.35rem;
}

.sidebarNav {
  flex: 1;
  padding: 1.5rem 0;
}

.sidebarNav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.navLink {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: color-mix(in srgb, var(--vt-on-deep) 65%, transparent);
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
}

.navLink::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 70%;
  background: var(--vt-accent);
  border-radius: 0 3px 3px 0;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.navLink:hover,
.navLink:focus-visible {
  color: var(--vt-on-deep);
  background: color-mix(in srgb, var(--vt-on-deep) 6%, transparent);
  outline: none;
}

.navLink:hover::before,
.navLink:focus-visible::before {
  transform: translateY(-50%) scaleY(1);
}

.navIcon {
  width: 20px;
  text-align: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.sidebarFooter {
  padding: 1.5rem;
  border-top: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
  font-size: 0.78rem;
  color: color-mix(in srgb, var(--vt-on-deep) 50%, transparent);
  line-height: 1.6;
}

.sidebarFooter strong {
  color: var(--vt-accent-on-deep);
  font-weight: 600;
}

/* Main content area */
.main {
  margin-left: 260px;
  min-height: 100vh;
}

/* Hero */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: clamp(3rem, 6vw, 6rem);
  background:
    radial-gradient(ellipse at 20% 80%, color-mix(in srgb, var(--vt-accent-ink) 15%, transparent) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, color-mix(in srgb, var(--vt-accent) 12%, transparent) 0%, transparent 50%),
    var(--vt-surface);
  overflow: hidden;
}

.heroContent {
  max-width: 640px;
  position: relative;
  z-index: 2;
}

.heroBadge {
  display: inline-block;
  padding: 0.4rem 1rem;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 50px;
  margin-bottom: 1.5rem;
}

.heroTitle {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
}

.heroSubtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

/* Decorative scoops */
.heroDeco {
  position: absolute;
  right: -2%;
  top: 50%;
  transform: translateY(-50%);
  width: clamp(280px, 35vw, 500px);
  height: clamp(280px, 35vw, 500px);
  z-index: 1;
}

.scoop {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset 0 -10px 30px rgba(0,0,0,0.08), 0 6px 20px rgba(0,0,0,0.06);
}

